import Foundation

/// CLIP's byte-pair-encoding tokenizer, ported from `open_clip`'s
/// `SimpleTokenizer`.
///
/// Needed because natural-language photo search runs the user's query through
/// CLIP's text tower, and the tower only accepts token IDs. There is no Apple
/// API for this, and a mismatch does not fail loudly — it just makes every
/// search a little worse. So this is tested against token IDs generated by
/// `open_clip` itself (see `tools/ref_openclip.py`) rather than against itself.
///
/// `open_clip` is the authority here rather than Hugging Face's
/// `CLIPTokenizerFast`, because `open_clip` trained these weights. The two
/// disagree on 9 of 37 test inputs — Hugging Face skips the text-cleaning step
/// entirely, so it mangles curly apostrophes, fullwidth characters and HTML
/// entities. `CLIPTokenizerTests` records every disagreement.
///
/// The algorithm, in `open_clip`'s order:
///
/// 1. Clean the text (`CLIPTextCleaner`).
/// 2. Split with a regex that treats contractions, letters, **single digits**
///    and punctuation runs as separate pieces.
/// 3. Re-encode each piece's UTF-8 bytes into the GPT-2 "byte alphabet".
/// 4. Apply BPE merges by rank until none apply.
/// 5. Map the resulting sub-words to IDs.
///
/// Step 2's single-digit rule is worth noting: `open_clip` uses `[\p{N}]`, not
/// `[\p{N}]+`, so "2024" becomes four tokens. Original OpenAI CLIP differs.
public struct CLIPTokenizer: Sendable {

    public enum LoadError: Error, CustomStringConvertible {
        case resourceMissing(String)
        case malformedVocabulary(String)

        public var description: String {
            switch self {
            case .resourceMissing(let name):
                return "Tokenizer resource '\(name)' is missing from the bundle."
            case .malformedVocabulary(let detail):
                return "Tokenizer vocabulary is malformed: \(detail)"
            }
        }
    }

    /// Start-of-text, 49406 in CLIP's vocabulary.
    public let startOfTextID: Int
    /// End-of-text, 49407.
    public let endOfTextID: Int
    /// CLIP's text tower takes exactly this many tokens.
    public static let contextLength = 77

    private let encoder: [String: Int]
    private let bpeRanks: [BytePair: Int]
    private let byteEncoder: [UInt8: Character]

    /// A merge candidate. A dedicated type rather than a tuple so it can be a
    /// dictionary key.
    private struct BytePair: Hashable {
        let first: String
        let second: String
    }

    // MARK: - Loading

    /// Loads the tokenizer from the vocabulary and merges bundled with TokinoKit.
    public init() throws {
        let bundle = Bundle.module
        guard let vocabURL = bundle.url(forResource: "Resources/clip-vocab", withExtension: "json")
        else { throw LoadError.resourceMissing("clip-vocab.json") }
        guard let mergesURL = bundle.url(forResource: "Resources/clip-merges", withExtension: "txt")
        else { throw LoadError.resourceMissing("clip-merges.txt") }

        try self.init(
            vocabularyJSON: try Data(contentsOf: vocabURL),
            mergesText: try String(contentsOf: mergesURL, encoding: .utf8)
        )
    }

    /// Loads from explicit data. Used by tests and by any future model whose
    /// vocabulary differs.
    public init(vocabularyJSON: Data, mergesText: String) throws {
        guard let decoded = try? JSONDecoder().decode([String: Int].self, from: vocabularyJSON)
        else { throw LoadError.malformedVocabulary("vocabulary is not a string-to-integer map") }
        self.encoder = decoded

        // open_clip names these "<start_of_text>" / "<end_of_text>" while the
        // Hugging Face vocabulary spells them "<|startoftext|>" /
        // "<|endoftext|>". The IDs are identical; only the spelling differs, so
        // accept either and fall back to the known constants.
        self.startOfTextID = decoded["<|startoftext|>"] ?? decoded["<start_of_text>"] ?? 49406
        self.endOfTextID = decoded["<|endoftext|>"] ?? decoded["<end_of_text>"] ?? 49407

        var ranks: [BytePair: Int] = [:]
        // The first line is a "#version:" header, not a merge rule.
        let lines = mergesText.split(separator: "\n", omittingEmptySubsequences: true)
        var rank = 0
        for line in lines {
            if line.hasPrefix("#") { continue }
            let parts = line.split(separator: " ")
            guard parts.count == 2 else { continue }
            ranks[BytePair(first: String(parts[0]), second: String(parts[1]))] = rank
            rank += 1
        }
        guard !ranks.isEmpty else {
            throw LoadError.malformedVocabulary("merges file contained no usable rules")
        }
        self.bpeRanks = ranks
        self.byteEncoder = Self.makeByteEncoder()
    }

    /// GPT-2's byte-to-unicode table, as `open_clip`'s `bytes_to_unicode`.
    ///
    /// Byte-level BPE needs every one of the 256 byte values to be a printable,
    /// non-whitespace character so the merge rules can be expressed as text.
    /// Bytes that are already printable map to themselves; the rest are shifted
    /// into an unused range starting at U+0100.
    private static func makeByteEncoder() -> [UInt8: Character] {
        var byteValues: [UInt8] = []
        byteValues.append(contentsOf: UInt8(33)...UInt8(126))   // '!' to '~'
        byteValues.append(contentsOf: UInt8(161)...UInt8(172))
        byteValues.append(contentsOf: UInt8(174)...UInt8(255))

        var scalars = byteValues.map { UInt32($0) }
        var nextUnused: UInt32 = 256
        for byte in UInt8.min...UInt8.max where !byteValues.contains(byte) {
            byteValues.append(byte)
            scalars.append(nextUnused)
            nextUnused += 1
        }

        var table: [UInt8: Character] = [:]
        for (byte, scalar) in zip(byteValues, scalars) {
            guard let unicode = Unicode.Scalar(scalar) else { continue }
            table[byte] = Character(unicode)
        }
        return table
    }

    // MARK: - Encoding

    /// Token IDs for `text`, without the start and end sentinels.
    ///
    /// Matches `open_clip`'s `encode(text, add_special_tokens=False)`, which is
    /// what the test fixture records.
    public func encode(_ text: String) -> [Int] {
        let cleaned = CLIPTextCleaner.clean(text)
        guard !cleaned.isEmpty else { return [] }

        var tokens: [Int] = []
        for piece in Self.split(cleaned) {
            // Re-encode the piece's UTF-8 bytes into the byte alphabet.
            let byteString = String(piece.utf8.compactMap { byteEncoder[$0] })
            guard !byteString.isEmpty else { continue }
            for subword in applyBPE(to: byteString) {
                if let id = encoder[subword] {
                    tokens.append(id)
                }
                // A sub-word absent from the vocabulary cannot happen with a
                // matched vocab/merges pair. Dropping it keeps a corrupt asset
                // from producing nonsense IDs that would silently skew results.
            }
        }
        return tokens
    }

    /// A model-ready sequence: start sentinel, tokens, end sentinel, padded with
    /// zeros to `contextLength`.
    ///
    /// Over-long input is truncated to `contextLength` and the last slot is
    /// forced back to the end sentinel, exactly as `open_clip` does — the tower
    /// relies on that token being present.
    public func tokenize(_ text: String, contextLength: Int = CLIPTokenizer.contextLength) -> [Int] {
        var tokens = [startOfTextID] + encode(text) + [endOfTextID]

        if tokens.count > contextLength {
            tokens = Array(tokens.prefix(contextLength))
            tokens[contextLength - 1] = endOfTextID
        } else if tokens.count < contextLength {
            tokens.append(contentsOf: repeatElement(0, count: contextLength - tokens.count))
        }
        return tokens
    }

    // MARK: - Splitting

    /// Splits cleaned text the way `open_clip`'s pattern does:
    ///
    /// ```
    /// 's|'t|'re|'ve|'m|'ll|'d|[\p{L}]+|[\p{N}]|[^\s\p{L}\p{N}]+
    /// ```
    ///
    /// Hand-written rather than using `NSRegularExpression` so that TokinoKit
    /// stays Foundation-only and behaves identically on Linux and iOS, where
    /// `NSRegularExpression`'s Unicode property support has differed.
    ///
    /// The contraction alternatives come first and so win over the letter rule,
    /// which is why "don't" splits as "don" + "'t" rather than "don" + "'" +
    /// "t".
    static func split(_ text: String) -> [String] {
        let characters = Array(text)
        var pieces: [String] = []
        var index = 0

        while index < characters.count {
            let character = characters[index]

            if character.isWhitespace {
                index += 1
                continue
            }

            if character == "'", let contraction = matchContraction(characters, at: index) {
                pieces.append(contraction)
                index += contraction.count
                continue
            }

            if character.isLetter {
                var end = index
                while end < characters.count, characters[end].isLetter { end += 1 }
                pieces.append(String(characters[index..<end]))
                index = end
                continue
            }

            if character.isNumber {
                // One digit at a time: open_clip's pattern is [\p{N}], not
                // [\p{N}]+, so "2024" becomes four tokens.
                pieces.append(String(character))
                index += 1
                continue
            }

            // Anything else: a run of non-space, non-letter, non-digit.
            var end = index
            while end < characters.count {
                let candidate = characters[end]
                if candidate.isWhitespace || candidate.isLetter || candidate.isNumber { break }
                if candidate == "'", matchContraction(characters, at: end) != nil, end > index {
                    break
                }
                end += 1
            }
            pieces.append(String(characters[index..<end]))
            index = end
        }

        return pieces
    }

    /// The contraction suffixes in `open_clip`'s pattern. Longest first, so
    /// "'re" is not matched as "'r" would be by a shorter alternative.
    private static let contractions = ["'re", "'ve", "'ll", "'s", "'t", "'m", "'d"]

    private static func matchContraction(_ characters: [Character], at index: Int) -> String? {
        for contraction in contractions {
            let length = contraction.count
            guard index + length <= characters.count else { continue }
            if String(characters[index..<(index + length)]).lowercased() == contraction {
                return String(characters[index..<(index + length)])
            }
        }
        return nil
    }

    // MARK: - Byte-pair encoding

    /// Repeatedly merges the highest-ranked adjacent pair until none remain.
    ///
    /// The end-of-word marker is appended to the final symbol, which is how CLIP
    /// distinguishes "dog" ending a word from "dog" inside "dogma".
    private func applyBPE(to token: String) -> [String] {
        var word = token.map(String.init)
        guard word.count > 1 else { return [token + "</w>"] }
        word[word.count - 1] += "</w>"

        while word.count > 1 {
            var bestRank = Int.max
            var bestIndex: Int?
            for index in 0..<(word.count - 1) {
                let pair = BytePair(first: word[index], second: word[index + 1])
                if let rank = bpeRanks[pair], rank < bestRank {
                    bestRank = rank
                    bestIndex = index
                }
            }
            guard let mergeIndex = bestIndex else { break }

            // Merge every non-overlapping occurrence of the winning pair, which
            // is what the reference implementation's inner loop does.
            let first = word[mergeIndex]
            let second = word[mergeIndex + 1]
            var merged: [String] = []
            var index = 0
            while index < word.count {
                if index < word.count - 1, word[index] == first, word[index + 1] == second {
                    merged.append(first + second)
                    index += 2
                } else {
                    merged.append(word[index])
                    index += 1
                }
            }
            word = merged
        }

        return word
    }
}
